local ActivityOpenLatticeMainGridCell = Class('ActivityOpenLatticeMainGridCell')
function ActivityOpenLatticeMainGridCell:__init()
    self.callBack = nil
    self.data = nil
end

function ActivityOpenLatticeMainGridCell:__delete()
    self.callBack = nil
    self.data = nil
end

function ActivityOpenLatticeMainGridCell:Awake()
    SetButtonAction(self.Close.gameObject,Bind(self,self.OnBtnCloseClick))
end

function ActivityOpenLatticeMainGridCell:SetButtonAction(co)
    self.callBack = co
end

function ActivityOpenLatticeMainGridCell:Start()

end

function ActivityOpenLatticeMainGridCell:RefreshGridUI(data)
    if not data then return end
    self.data = data
    KTool.SetActive(self.Close.gameObject, self.data.gridId == 0)
    KTool.SetActive(self.Open.gameObject, self.data.gridId ~= 0)

    if self.data.gridId > 0 then
        local openGridRewardVo = CfUtils.GetCfVo(AutoIds.IdSetting6129, "OpenGridRewardVo", self.data.gridId)
        if isTable(openGridRewardVo) then
            CfUtils.FillText(self.TextNumber, openGridRewardVo.rewardNum)
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(openGridRewardVo.reward)
            if isTable(vo) then
                self.ImgGoodsIcon:LoadSprite(vo.photoPath)
            end
        end
    end

    KTool.SetActive(self.ImgStatusGrandReward.gameObject,self.data.isBigReward)
    KTool.SetActive(self.ImgBgBigReward.gameObject,self.data.isBigReward)
    KTool.SetActive(self.ImgBg.gameObject,not self.data.isBigReward)
end

function ActivityOpenLatticeMainGridCell:PlayOpenAni()
   local name = "ActivityOpenLatticeMainDialog_Cell_Open"
    self.AniRoot:Play(name)
end

function ActivityOpenLatticeMainGridCell:PlayCloseAni()
    local name = "ActivityOpenLatticeMainDialog_Cell_Close"
    self.AniRoot:Play(name)
end

function ActivityOpenLatticeMainGridCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end
---开格子
function ActivityOpenLatticeMainGridCell:OnBtnCloseClick()
    ---格子序号等于0才能开  大于说明已经开启过了
    if self.data.gridId == 0 then
        if not isNull(self.callBack) then
            self.callBack()
        end
    end
end

return ActivityOpenLatticeMainGridCell